function i(t){return String(t).padStart(2,"0")}function o(t){if(!t)return"-";const n=new Date(t);return Number.isNaN(n.getTime())?String(t):`${n.getFullYear()}-${i(n.getMonth()+1)}-${i(n.getDate())} ${i(n.getHours())}:${i(n.getMinutes())}:${i(n.getSeconds())}`}function e(t,n=2){return t==null||t===""?"-":typeof t=="string"?t:t.toFixed(n)}function s(t,n){const r=e(t,2);return r==="-"?"-":n?`${r} ${n}`:r}function f(t){return t==null||t===""?"-":t}function u(t,n=60){return t?t.length>n?`${t.slice(0,n)}…`:t:"-"}function c(t){if(!(t==null||t===""))return String(t)}function d(t){const n=t.trim();if(!n)return null;try{const r=JSON.parse(n)??null;return r&&typeof r=="object"&&!Array.isArray(r)?r:null}catch{return null}}function g(t){if(t==null)return"";try{return JSON.stringify(t,null,2)}catch{return String(t)}}export{e as a,s as b,u as c,g as d,o as f,d as p,c as s,f as t};
